using SQLite; using FoodExpiryApp.Models; namespace FoodExpiryApp; public class ProductRepository { readonly SQLiteAsyncConnection db; public ProductRepository(){db=new SQLiteAsyncConnection(Path.Combine(FileSystem.AppDataDirectory,"foodexpiry.db3"));db.CreateTableAsync<Product>().Wait(); Seed();} async void Seed(){if(await db.Table<Product>().CountAsync()>0)return;await db.InsertAllAsync(new[]{new Product{Name="Молоко",Brand="Простоквашино",Variant="2.5%",Category="Молочные",Volume="0,930 л",ExpiryDate=DateTime.Today.AddDays(6)},new Product{Name="Молоко",Brand="Простоквашино",Variant="2.5%",Category="Молочные",Volume="0,930 л",ExpiryDate=DateTime.Today.AddDays(18)},new Product{Name="Вода",Brand="Байкальская",Category="Напитки",Volume="0,5 л",ExpiryDate=DateTime.Today.AddDays(22)}});} public Task<List<Product>> All()=>db.Table<Product>().OrderBy(p=>p.Name).ToListAsync(); public Task<int> Save(Product p)=>p.Id==0?db.InsertAsync(p):db.UpdateAsync(p); public Task<int> Delete(Product p)=>db.DeleteAsync(p); }
